from numba import njit

@njit
def solve_eigh_f32(A):
    return np.linalg.eigh(A)

@njit
def qr_ortho(X):
    q, r = np.linalg.qr(X)
    signs = np.sign(np.diag(r))
    for i in range(X.shape[1]):
        q[:, i] *= signs[i]
    return q

@njit
def process_solution(evals, evecs):
    evals = evals[::-1].astype(np.float64)
    evecs = evecs[:, ::-1].astype(np.float64)
    evecs = qr_ortho(evecs)
    return evals, evecs

