import numpy as np
import scipy.optimize as opt
from reference import Task

def solve_scipy(problem):
    c = np.array(problem["c"])
    A = np.array(problem["A"])
    b = np.array(problem["b"])

    # Primal problem:
    # max c^T x - \sum \log x_i
    # s.t. Ax = b

    # Let's use scipy.optimize.minimize on the primal problem
    def obj(x):
        if np.any(x <= 0):
            return np.inf
        return -(c.dot(x) - np.sum(np.log(x)))

    def jac(x):
        return -(c - 1.0 / x)

    def hess(x):
        return np.diag(1.0 / (x**2))

    constraints = {'type': 'eq', 'fun': lambda x: A @ x - b, 'jac': lambda x: A}

    # Find initial feasible point
    # min ||Ax - b||^2 s.t. x >= 1
    res0 = opt.lsq_linear(A, b, bounds=(1e-2, np.inf))
    x0 = res0.x

    res = opt.minimize(obj, x0, jac=jac, hess=hess, method='trust-constr', constraints=constraints, options={'gtol': 1e-12, 'xtol': 1e-12})
    return {"solution": res.x.tolist()}

task = Task()
prob = task.generate_problem(50)
sol_ref = task.solve(prob)
sol_newton = solve_scipy(prob)

print("Ref:", sol_ref["solution"][:5])
print("New:", sol_newton["solution"][:5])
print("Match:", np.allclose(sol_ref["solution"], sol_newton["solution"], atol=1e-6))
